function isDarkHex(hex: string) {
  const value = Number.parseInt(hex, 16);
  const r = (value >> 16) & 255;
  const g = (value >> 8) & 255;
  const b = value & 255;
  return 0.2126 * r + 0.7152 * g + 0.0722 * b < 56;
}

function PathIcon({
  path,
  hex,
  className,
}: {
  path: string;
  hex: string;
  className?: string;
}) {
  const invert = isDarkHex(hex);

  return (
    <svg
      viewBox="0 0 24 24"
      className={`${className ?? ""} ${invert ? "skill-icon-invert" : ""}`}
      style={{ color: `#${hex}` }}
      aria-hidden="true"
    >
      <path fill="currentColor" d={path} />
    </svg>
  );
}

function RestIcon({ className }: IconSvgProps) {
  return (
    <svg
      viewBox="0 0 24 24"
      className={className}
      style={{ color: "var(--accent-color)" }}
      aria-hidden="true"
    >
      <g
        fill="none"
        stroke="currentColor"
        strokeWidth="2.1"
        strokeLinecap="round"
        strokeLinejoin="round"
      >
        <path d="M8.2 6.2 3.2 12l5 5.8" />
        <path d="M15.8 6.2 20.8 12l-5 5.8" />
        <path d="M13.4 5.2 10.6 18.8" />
      </g>
    </svg>
  );
}

