function NotifeeIcon({ className }: IconSvgProps) {
  return (
    <svg viewBox="0 0 24 24" className={className} aria-hidden="true">
      <path
        fill="#f97316"
        d="M12 2.5c-3.2 0-5.7 2.4-5.7 5.4v3.2c0 .5-.2.9-.5 1.3l-1.5 1.8c-.6.7-.1 1.8.8 1.8h14c.9 0 1.4-1.1.8-1.8l-1.5-1.8c-.3-.4-.5-.8-.5-1.3V7.9c0-3-2.5-5.4-5.7-5.4zm-2.1 15.3a2.1 2.1 0 0 0 4.2 0z"
      />
      <circle cx="17.4" cy="5.2" r="2.2" fill="#ea580c" />
    </svg>
  );
}

type SkillIconProps = {
  name: string;
  icon: string;
  className?: string;
};

export function SkillIcon({ name, icon, className }: SkillIconProps) {
  const simple = SIMPLE_ICONS[icon];
  if (simple) {
    return (
      <PathIcon path={simple.path} hex={simple.hex} className={className} />
    );
  }

  const custom = CUSTOM_PATHS[icon];
  if (custom) {
    return (
      <PathIcon path={custom.path} hex={custom.hex} className={className} />
    );
  }

  if (icon === "rest") {
    return <RestIcon className={className} />;
  }

  if (icon === "microservices") {
    return <MicroservicesIcon className={className} />;
  }

  if (icon === "notifee") {
    return <NotifeeIcon className={className} />;
  }

  return (
    <span className="text-xs font-medium" aria-hidden="true">
      {name}
    </span>
  );
}
